pub fn squash(v: &mut Vec<String>) {
    // Dedup on the ORIGINAL values, keeping the first of each run.
    v.dedup();

    // Then trim ASCII whitespace (space, \t, \n, \r, \x0B, \x0C) from both ends.
    for s in v.iter_mut() {
        let b = s.as_bytes();
        let is_ws = |c: u8| matches!(c, b' ' | b'\t' | b'\n' | b'\r' | 0x0B | 0x0C);
        let mut lo = 0;
        let mut hi = b.len();
        while lo < hi && is_ws(b[lo]) {
            lo += 1;
        }
        while hi > lo && is_ws(b[hi - 1]) {
            hi -= 1;
        }
        *s = s[lo..hi].to_string();
    }
}
