```rust
use std::sync::Arc;
use std::thread;

pub fn parallel_map<T, R, F>(items: Vec<T>, f: F, workers: usize) -> Vec<R>
where
    T: Send + 'static,
    R: Send + 'static,
    F: Fn(T) -> R + Send + Sync + 'static,
{
    let n = items.len();

    // Split points for `workers` contiguous chunks (contiguous so each
    // worker's results stay in input order; concat in worker order = input order).
    let mut splits = Vec::with_capacity(workers + 1);
    for w in 0..=workers {
        splits.push(n * w / workers);
    }

    let mut items = items;
    let mut offset = 0usize;
    let mut chunks: Vec<Vec<T>> = Vec::with_capacity(workers);
    for w in 0..workers {
        let start = splits[w] - offset;
        let end = splits[w + 1] - offset;
        offset += end - start;
        chunks.push(items.drain(start..end).collect());
    }
    let f = Arc::new(f);

    // Exactly `workers` OS threads, one per chunk (never one per item).
    let mut handles = Vec::with_capacity(workers);
    for chunk in chunks {
        let f = Arc::clone(&f);
        handles.push(thread::spawn(move || {
            let mut out = Vec::with_capacity(chunk.len());
            for x in chunk {
                out.push(f(x));
            }
            out
        }));
    }

    // Join in spawn order; contiguous chunks keep results in original input order.
    let mut results = Vec::with_capacity(n);
    for h in handles {
        results.extend(h.join().expect("worker thread panicked"));
    }
    results
}
