```rust
use std::marker::PhantomData;

pub struct PairsMut<'a, T> {
    ptr: *mut T,
    len: usize,
    _marker: PhantomData<&'a mut T>,
}

pub fn pairs_mut<T>(s: &mut [T]) -> PairsMut<'_, T> {
    PairsMut {
        ptr: s.as_mut_ptr(),
        len: s.len(),
        _marker: PhantomData,
    }
}

impl<'a, T> Iterator for PairsMut<'a, T> {
    type Item = (&'a mut T, &'a mut T);

    fn next(&mut self) -> Option<(&'a mut T, &'a mut T)> {
        if self.len < 2 {
            return None;
        }

        // SAFETY:
        // - `pairs_mut` obtained the slice as `&mut [T]`, so this iterator
        //   owns exclusive access to every element for `'a`; `self.ptr`
        //   points into that region with `self.len` live, aligned,
        //   contiguous `T`s remaining (here >= 2).
        // - The two references cover the disjoint single-element regions
        //   `[ptr, ptr+1)` and `[ptr+1, ptr+2)`; for ZSTs they occupy no
        //   memory, so no aliasing is possible.
        // - We advance `self.ptr` past both elements (inside the same
        //   unsafe block, before the references are handed out) and
        //   shrink `self.len`, so no element is ever handed out twice.
        let (first, second) = unsafe {
            let first = &mut *self.ptr;
            let second = &mut *self.ptr.add(1);
            self.ptr = self.ptr.add(2);
            (first, second)
        };
        self.len -= 2;
        Some((first, second))
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let n = self.len / 2;
        (n, Some(n))
    }
}
