```rust
use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Wake, Waker};

/// Shared waker state: a condvar (the park point) plus a monotonic wake
/// counter. The counter makes the design race-free: any `wake()` (from any
/// thread, at any time) increments it, and the poller only re-polls once
/// the counter has moved past the value it saw before it polled the future.
struct WakerState {
    cv: Condvar,
    wake_count: Mutex<u64>,
}

struct MyWaker(Arc<WakerState>);

impl Wake for MyWaker {
    fn wake(self: Arc<Self>) {
        Self::wake_by_ref(&self);
    }

    fn wake_by_ref(self: &Arc<Self>) {
        *self.0.wake_count.lock().unwrap() += 1;
        self.0.cv.notify_one();
    }
}

/// Polls `fut` to completion on the current thread.
///
/// The future is only ever re-polled after its waker has been invoked. On
/// `Pending` the thread parks on a condvar; a `wake()` from any thread
/// (including after a delay) bumps the counter and wakes us. Because the
/// baseline is captured *before* each poll, a wake that arrives while we are
/// already about to park is not lost.
pub fn block_on<F: Future>(fut: F) -> F::Output {
    let state = Arc::new(WakerState {
        cv: Condvar::new(),
        wake_count: Mutex::new(0),
    });
    let waker: Waker = Arc::new(MyWaker(Arc::clone(&state))).into();
    let mut cx = Context::from_waker(&waker);
    let mut fut = Box::pin(fut);

    loop {
        // Snapshot the wake count before polling. Any wake() during or after
        // this poll will push the counter past this baseline.
        let baseline = *state.wake_count.lock().unwrap();

        match fut.as_mut().poll(&mut cx) {
            Poll::Ready(out) => return out,
            Poll::Pending => {
                let mut count = state.wake_count.lock().unwrap();
                // Sleep until a wake() moves the counter past the baseline.
                // Re-checked in a loop, so spurious wakeups are harmless and
                // a wakeup that fired just before we parked is still seen.
                while *count == baseline {
                    count = state.cv.wait(count).unwrap();
                }
            }
        }
    }
}

/// Yields to the executor `remaining` times, then resolves.
///
/// Each poll with `remaining > 0` decrements the counter, wakes the waker by
/// reference, and returns `Pending`; a poll with `remaining == 0` resolves
/// `Ready(())`.
pub struct YieldNow {
    pub remaining: u32,
}

impl Future for YieldNow {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let this = self.get_mut();
        if this.remaining > 0 {
            this.remaining -= 1;
            cx.waker().wake_by_ref();
            Poll::Pending
        } else {
            Poll::Ready(())
        }
    }
}
